import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    d = int(data[1])
    l = int(data[2])

    if n == 1:
        if 1 <= d <= l:
            print(d)
        else:
            print(-1)
        return

    coeff = [0] * n
    coeff[n-1] = 1
    coeff[n-2] = -1

    for i in range(n-2, 0, -1):
        new_coeff = [0] * i
        for j in range(i-1):
            new_coeff[j] = coeff[j]
        new_coeff[i-1] = coeff[i-1] - coeff[i]
        coeff = new_coeff

    pos_coeffs = []
    neg_coeffs = []
    for i in range(n):
        if coeff[i] > 0:
            pos_coeffs.append((i, coeff[i]))
        elif coeff[i] < 0:
            neg_coeffs.append((i, -coeff[i]))

    if not pos_coeffs and not neg_coeffs:
        if d == 0:
            print(' '.join(['1'] * n))
        else:
            print(-1)
        return

    if not pos_coeffs:
        print(-1)
        return

    if not neg_coeffs:
        print(-1)
        return

    pos_sum = sum(c for _, c in pos_coeffs)
    neg_sum = sum(c for _, c in neg_coeffs)

    if d % (pos_sum + neg_sum) != 0:
        print(-1)
        return

    base = d // (pos_sum + neg_sum)
    remainder = d - base * (pos_sum + neg_sum)

    if remainder != 0:
        print(-1)
        return

    if base < 1:
        print(-1)
        return

    res = [base] * n

    for i, c in pos_coeffs:
        if res[i] > l:
            print(-1)
            return
        res[i] += c

    for i, c in neg_coeffs:
        if res[i] < 1:
            print(-1)
            return
        res[i] -= c

    if not all(1 <= x <= l for x in res):
        print(-1)
        return

    total = 0
    for i in range(n):
        total += res[i] * coeff[i]

    if total != d:
        print(-1)
        return

    print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()
